import type Redis from "ioredis";

export interface QueueMessage {
  jobId: string;
  tenantId: string;
  enqueuedAt: number;
}

export class JobQueue {
  constructor(private readonly redis: Redis, private readonly stream = "lantern:jobs") {}

  async enqueue(message: QueueMessage): Promise<string> {
    return this.redis.xadd(this.stream, "MAXLEN", "~", 10000, "*", "job", JSON.stringify(message));
  }

  async read(consumer: string, group: string): Promise<[string, string[]][]> {
    const reply = await this.redis.xreadgroup(
      "GROUP", group, consumer, "COUNT", 1, "BLOCK", 1000, "STREAMS", this.stream, ">",
    );
    if (!reply) return [];
    return (reply[0]?.[1] ?? []) as [string, string[]][];
  }
}
