export class OutboxPublisher {
  private stopped = false;
  constructor(private readonly pool: Pool, private readonly redis: Redis, private readonly outbox: OutboxRepository) {}

  async run(): Promise<void> {
    while (!this.stopped) {
      const client = await this.pool.connect();
      try {
        await client.query("BEGIN");
        const rows = await this.outbox.pending(client, 100);
        for (const row of rows) {
          const event = row.payload as JobEvent;
          await this.redis.publish(`lantern:events:${row.tenantId}:${row.jobId}`, JSON.stringify(event));
          await this.outbox.markPublished(client, row.id);
        }
        await client.query("COMMIT");
        if (rows.length === 0) await new Promise((resolve) => setTimeout(resolve, 100));
      } catch (error) {
        await client.query("ROLLBACK");
        throw error;
      } finally {
        client.release();
      }
    }
  }

  stop(): void { this.stopped = true; }
}
