import { createHash } from "node:crypto";

export interface RenderInput { inputUri: string; renderer: string; }
export interface RenderOutput { outputUri: string; checksum: string; }

export interface RenderEngine {
  render(input: RenderInput, onProgress: (completed: number, total: number) => Promise<void>): Promise<RenderOutput>;
}

export class LocalRenderEngine implements RenderEngine {
  async render(input: RenderInput, onProgress: (completed: number, total: number) => Promise<void>): Promise<RenderOutput> {
    const total = input.renderer === "svg" ? 3 : 12;
    const chunks: Buffer[] = [];
    for (let i = 0; i < total; i++) {
      await new Promise((resolve) => setTimeout(resolve, 15));
      const chunk = Buffer.from(`${input.renderer}:${input.inputUri}:${i}\n`);
      chunks.push(chunk);
      await onProgress(i + 1, total);
    }
    const output = Buffer.concat(chunks);
    return { outputUri: `s3://lantern-output/${Date.now()}-${input.renderer}`, checksum: createHash("sha256").update(output).digest("hex") };
  }
}
