```ts
import { randomUUID } from "node:crypto";
import { Pool } from "pg";
import Redis from "ioredis";
import { JobRepository } from "../../api/src/infra/postgres/job-repository.js";
import { OutboxRepository } from "../../api/src/infra/postgres/outbox-repository.js";
import { EventStore } from "../../../packages/events/src/event-store.js";
import { LeaseLostError } from "../../../packages/shared/src/errors.js";
import { loadConfig } from "../../../packages/config/src/index.js";
import { LocalRenderEngine } from "./render/render-engine.js";

const config = loadConfig(process.env);
const pool = new Pool({ connectionString: config.databaseUrl, max: 8 });
const redis = new Redis(config.redisUrl);
const jobs = new JobRepository(pool);
const outbox = new OutboxRepository();
const eventStore = new EventStore(pool);
const engine = new LocalRenderEngine();
const workerId = `${config.hostname}:${process.pid}`;

async function processMessage(raw: string): Promise<void> {
  const message = JSON.parse(raw) as { tenantId: string; jobId: string };
  const leaseId = randomUUID();
  const expiresAt = new Date(Date.now() + config.leaseTtlMs);
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const job = await jobs.claimNext(client, workerId, leaseId, expiresAt);
    if (!job || job.id !== message.jobId || job.tenantId !== message.tenantId) {
      await client.query("ROLLBACK");
      return;
    }
    const started: any = {
      eventId: randomUUID(), tenantId: job.tenantId, jobId: job.id,
      sequence: job.version, occurredAt: new Date().toISOString(),
      type: "job.started", state: "running", payload: { workerId, leaseId },
    };
    await eventStore.append(client, started);
    await outbox.append(client, started);
    await client.query("COMMIT");

    const output = await engine.render(job, async (completed, total) => {
      await publishProgress(job.tenantId, job.id, leaseId, completed, total);
    });

    const finishClient = await pool.connect();
    try {
      await finishClient.query("BEGIN");
      const finished = await jobs.markSucceeded(finishClient, job.tenantId, job.id, leaseId, output.outputUri, output.checksum);
      if (!finished) throw new LeaseLostError();
      const event: any = {
        eventId: randomUUID(), tenantId: job.tenantId, jobId: job.id,
        sequence: finished.version, occurredAt: finished.updatedAt.toISOString(),
        type: "job.succeeded", state: "succeeded",
        payload: { outputUri: output.outputUri, checksum: output.checksum },
      };
      await eventStore.append(finishClient, event);
      await outbox.append(finishClient, event);
      await finishClient.query("COMMIT");
    } catch (error) {
      await finishClient.query("ROLLBACK");
      throw error;
    } finally {
      finishClient.release();
    }
  } finally {
    client.release();
  }
}

async function publishProgress(tenantId: string, jobId: string, leaseId: string, completed: number, total: number): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const result = await client.query(
      `SELECT state, version, lease_id FROM jobs WHERE tenant_id = $1 AND id = $2 FOR UPDATE`,
      [tenantId, jobId],
    );
    const row = result.rows[0];
    if (!row || row.lease_id !== leaseId || row.state !== "running") throw new LeaseLostError();
    const sequence = Number(row.version) + 1;
    const event: any = {
      eventId: randomUUID(), tenantId, jobId, sequence,
      occurredAt: new Date().toISOString(), type: "job.progress", state: "running",
      payload: { completed, total },
    };
    await client.query(`UPDATE jobs SET version = $3, next_event_sequence = $3 + 1, updated_at = now() WHERE tenant_id = $1 AND id = $2`, [tenantId, jobId, sequence]);
    await eventStore.append(client, event);
    await outbox.append(client, event);
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally { client.release(); }
}

async function main(): Promise<void> {
  const group = "render-workers";
  await redis.xgroup("CREATE", "lantern:jobs", group, "$", "MKSTREAM").catch((error: any) => {
    if (!String(error.message).includes("BUSYGROUP")) throw error;
  });
  while (true) {
    const messages = await redis.xreadgroup("GROUP", group, workerId, "COUNT", 1, "BLOCK", 1000, "STREAMS", "lantern:jobs", ">");
    for (const [, entries] of messages ?? []) {
      for (const [id, fields] of entries as [string, string[]][]) {
        const raw = fields[fields.indexOf("job") + 1];
        try {
          await processMessage(raw);
          await redis.xack("lantern:jobs", group, id);
        } catch (error) {
          console.error({ error, id }, "job failed");
          await redis.xclaim("lantern:jobs", group, workerId, 0, id);
        }
      }
    }
  }
}

void main();
